import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.DajbkT6K.js";const r="/aibutler/docs/img/settings-models.png",l="/aibutler/docs/img/persona-ai.png",m=JSON.parse('{"title":"接入模型","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md"}'),i={name:"guide/models.md"};function n(s,t,c,h,p,u){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="接入模型" tabindex="-1">接入模型 <a class="header-anchor" href="#接入模型" aria-label="Permalink to &quot;接入模型&quot;">​</a></h1><p>人格要接上 AI 模型才能思考和说话。有两条路：<strong>Claude 订阅</strong>，或者<strong>自己的 API Key</strong>。两条可以同时开着，每个人格各选各的。</p><div class="tip custom-block"><p class="custom-block-title">不会配？</p><p>直接问人格：「我有一个 DeepSeek 的 key，怎么接？」它会告诉你每一步点哪里。</p></div><h2 id="两个地方-各管一件事" tabindex="-1">两个地方，各管一件事 <a class="header-anchor" href="#两个地方-各管一件事" aria-label="Permalink to &quot;两个地方，各管一件事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>在哪</th><th>管什么</th></tr></thead><tbody><tr><td><strong>系统设置</strong>（主窗口右上角 ⚙）</td><td>存「钥匙」：Claude 订阅、API Key。存着不等于在用。</td></tr><tr><td><strong>人格管理</strong> → 某个人格 → 「AI」页</td><td>这个人格用哪把钥匙、哪个引擎、哪个模型。</td></tr></tbody></table><p>先在系统设置里存好，再到人格那边选用。</p><h2 id="方式一-claude-订阅" tabindex="-1">方式一：Claude 订阅 <a class="header-anchor" href="#方式一-claude-订阅" aria-label="Permalink to &quot;方式一：Claude 订阅&quot;">​</a></h2><p>有 Claude Pro 或 Max 订阅，就能让人格用订阅来跑。</p><ol><li>打开系统设置 →「模型服务」→「Claude 订阅」，点「开启」。</li><li>确认后会下载 Anthropic 的 Claude Agent SDK（约 110 MB），下载完点「立即重启」。</li><li>重启后点「登录 Claude」，在浏览器里登录授权。</li><li>看到「已开启并登录」就好了。</li></ol><p>然后到人格的「AI」页，「接入方式」选「用订阅账号」。</p><h2 id="方式二-api-key" tabindex="-1">方式二：API Key <a class="header-anchor" href="#方式二-api-key" aria-label="Permalink to &quot;方式二：API Key&quot;">​</a></h2><h3 id="存一把-key" tabindex="-1">存一把 Key <a class="header-anchor" href="#存一把-key" aria-label="Permalink to &quot;存一把 Key&quot;">​</a></h3><p>打开系统设置 →「模型服务」→「API 凭据」，点「＋ 加一条」，填三项：</p><table tabindex="0"><thead><tr><th>项</th><th>填什么</th></tr></thead><tbody><tr><td>名字</td><td>自己认得出就行，比如「DeepSeek」「公司网关」</td></tr><tr><td>地址（base_url）</td><td>服务商给的接口地址，留空默认是 <code>https://api.anthropic.com</code></td></tr><tr><td>Key</td><td>服务商给的 API Key</td></tr></tbody></table><p><img src="'+r+'" alt="系统设置里的 API 凭据"></p><p>填完点「保存」，再点「测试」确认能连上。可以存多条。勾了「默认」的那条，是人格没选凭据、或选的那条被删掉时用的。</p><h3 id="让人格用它" tabindex="-1">让人格用它 <a class="header-anchor" href="#让人格用它" aria-label="Permalink to &quot;让人格用它&quot;">​</a></h3><p>到人格管理 → 这个人格 →「AI」页：</p><ol><li><strong>接入方式</strong>：选「用系统设置里存的 key」，再选是哪一条。</li><li><strong>引擎</strong>：一般选「Butler 引擎（多模型）」。</li><li><strong>模型</strong>：从下拉里选；列表里没有的，选「其它 · 手动输入模型名」自己填。</li></ol><p><img src="'+l+'" alt="人格的「AI」页"></p><p>改完要重新打开这个人格才生效。</p><h3 id="常见服务商怎么填" tabindex="-1">常见服务商怎么填 <a class="header-anchor" href="#常见服务商怎么填" aria-label="Permalink to &quot;常见服务商怎么填&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务商</th><th>地址</th><th>模型名的写法</th></tr></thead><tbody><tr><td>Anthropic 官方</td><td>留空</td><td>从下拉里选</td></tr><tr><td>走 Anthropic 协议的网关</td><td>网关给的地址</td><td>照网关给的写</td></tr><tr><td>通义千问（大陆）</td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td><td>前面加 <code>compat/</code>，如 <code>compat/qwen-plus</code></td></tr><tr><td>通义千问（国际）</td><td><code>https://dashscope-intl.aliyuncs.com/compatible-mode/v1</code></td><td>同上</td></tr><tr><td>豆包（火山方舟）</td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td><td>前面加 <code>compat/</code>，后面写方舟里的模型名</td></tr><tr><td>其它 OpenAI 兼容接口</td><td>服务商给的地址</td><td>前面加 <code>compat/</code></td></tr><tr><td>OpenAI 官方</td><td>留空</td><td>前面加 <code>openai/</code>，如 <code>openai/gpt-5.4-mini</code></td></tr></tbody></table><p><code>compat/</code> 的意思是「按 OpenAI 兼容接口去连」，<code>openai/</code> 是连 OpenAI 官方的新接口。不确定时先用「测试」试，或者问人格。</p><h2 id="两种引擎有什么区别" tabindex="-1">两种引擎有什么区别 <a class="header-anchor" href="#两种引擎有什么区别" aria-label="Permalink to &quot;两种引擎有什么区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Butler 引擎（多模型）</th><th>Claude Code</th></tr></thead><tbody><tr><td>是什么</td><td>全能管家自带的</td><td>Anthropic 官方的 Claude Agent SDK</td></tr><tr><td>能接的模型</td><td>Claude、OpenAI、国内大模型、各种网关</td><td>只有 Claude</td></tr><tr><td>什么时候用</td><td>用 API Key 时的默认选择</td><td>用 Claude 订阅时自动用它</td></tr></tbody></table><p>用订阅的人格固定走 Claude Code；用 Key 的人格两种都能选，「引擎」这一项只有装了 Claude 订阅组件后才会出现。</p><h2 id="联网搜索" tabindex="-1">联网搜索 <a class="header-anchor" href="#联网搜索" aria-label="Permalink to &quot;联网搜索&quot;">​</a></h2><p>用 Butler 引擎时，人格默认用模型自带的搜索（有的模型没有）。搜不了或想换，见 <a href="/aibutler/docs/guide/search.html">联网搜索</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>人格说「还没选模型，暂时无法回复」</strong> 去人格管理 → 这个人格 →「AI」页选一个模型。</p><p><strong>报 401 或「key 不对」</strong> 系统设置里那条 Key 点「测试」。不通就重新复制粘贴一遍 Key，注意前后不要带空格。</p><p><strong>报 400，有时好有时坏</strong> 多半是网关或服务商那边临时拒收，等一会儿再发。一直这样，换一条线路试试，或者把报错原文发给人格让它帮你看。</p><p><strong>想让几个人格用不同的模型</strong> 每个人格的「AI」页各选各的，互不影响。</p>',34)])])}const g=e(i,[["render",n]]);export{m as __pageData,g as default};
